+		Limit:  10,
+		Options: &resourcepb.ListOptions{
+			Key:    &resourcepb.ResourceKey{Namespace: "nsx", Group: "advisor.grafana.app", Resource: "advisors"},
+			Fields: []*resourcepb.Requirement{{Key: "spec.undeclared", Operator: "=", Values: []string{"bar"}}},
